static UB g_synthesized_tibetan[16];

const UB* get_tibetan_glyph_bitmap_ex(UW codepoint, H *out_width, H *out_height) {
    /* 1. Check 8x16 single-width raster glyphs */
    for (int i = 0; g_tibetan_8x16[i].codepoint != 0; i++) {
        if (g_tibetan_8x16[i].codepoint == codepoint) {
            if (out_width) *out_width = 8;
            if (out_height) *out_height = 16;
            return g_tibetan_8x16[i].bitmap;
        }
    }

    /* 2. Check 16x16 double-width raster glyphs */
    for (int i = 0; g_tibetan_16x16[i].codepoint != 0; i++) {
        if (g_tibetan_16x16[i].codepoint == codepoint) {
            if (out_width) *out_width = 16;
            if (out_height) *out_height = 16;
            return g_tibetan_16x16[i].bitmap;
        }
    }

    /* Fallback default 8x16 Tibetan glyph */
    memset(g_synthesized_tibetan, 0, sizeof(g_synthesized_tibetan));
    g_synthesized_tibetan[3] = 0x7E;
    for (int r = 4; r < 10; r++) g_synthesized_tibetan[r] = 0x18;
    if (out_width) *out_width = 8;
    if (out_height) *out_height = 16;
    return g_synthesized_tibetan;
}

const UB* get_tibetan_glyph_bitmap(UW codepoint) {
    H w = 8, h = 16;
    return get_tibetan_glyph_bitmap_ex(codepoint, &w, &h);
}

int render_tibetan_stack_bitmap(UW root_cp, UW sub_cp, UW vowel_cp, UB out_buf[32]) {
    if (!out_buf) return -1;
    memset(out_buf, 0, 32);

    H rw = 8, rh = 16;
    const UB *root_bmp = get_tibetan_glyph_bitmap_ex(root_cp, &rw, &rh);
    if (root_bmp) {
        for (int i = 0; i < 16; i++) out_buf[i * 2] |= root_bmp[i];
    }

    if (sub_cp != 0) {
        H sw = 8, sh = 16;
        const UB *sub_bmp = get_tibetan_glyph_bitmap_ex(sub_cp, &sw, &sh);
        if (sub_bmp) {
            for (int i = 0; i < 16; i++) out_buf[i * 2] |= sub_bmp[i];
        }
    }

    if (vowel_cp != 0) {
        H vw = 8, vh = 16;
        const UB *vowel_bmp = get_tibetan_glyph_bitmap_ex(vowel_cp, &vw, &vh);
        if (vowel_bmp) {
            for (int i = 0; i < 16; i++) out_buf[i * 2] |= vowel_bmp[i];
        }
    }

    return 0;
}
